"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[7065],{1741(e){e.exports=JSON.parse('{"title":"useCallback\uc744 \uc368\uc57c\ud560\uae4c?","date":"2025-08-06","coverUrl":"/kudzu-based-bench/assets/notion/b0814591b06db17d.png","html":"<h1 data-notion-block-id=\\"241e548d-8a8e-805b-ac0f-d694ff9a0086\\">Beyond the Article: \ud55c \uac78\uc74c \ub354</h1><h2 data-notion-block-id=\\"245e548d-8a8e-802c-bfe2-e8adb1a8d9d9\\" id=\\"245e548d-8a8e-802c-bfe2-e8adb1a8d9d9\\">useCallback\uc744 \uc368\uc57c\ud560\uae4c?</h2><a href=\\"https://tkdodo.eu/blog/the-useless-use-callback\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://tkdodo.eu/blog/the-useless-use-callback</a><p data-notion-block-id=\\"245e548d-8a8e-8092-a494-d5f31ea34071\\">hooks\uac00 \ucc98\uc74c \ub098\uc62c\ub54c\ubd80\ud130 \ub098\uc628 \uc624\ub79c \ub17c\uc7c1(<a href=\\"https://kentcdodds.com/blog/usememo-and-usecallback\\">Kent C dodds.\uc758 \uae00</a>, 2019\ub144\uc5d0 \ub098\uc654\uc2b5\ub2c8\ub2e4.)\uc774\uc9c0\ub9cc, \uc544\uc9c1\ub3c4 \uacc4\uc18d\ub418\ub294 \ub17c\uc7c1\uc785\ub2c8\ub2e4. \ub54c\uc5d0 \ub530\ub77c <a href=\\"https://ones-to-watch.ethansup.net/news/post/a5902c7d-ee33-4db6-aaea-ea4820a7562f#969cfc7b-5f89-42de-896d-eacff8b32799\\">useCallback\uc744 \uc0ac\uc6a9\ud560 \ub54c \uba54\ubaa8\ub9ac \ub204\uc218</a>\uac00 \uc0dd\uae30\uae30\ub3c4 \ud558\uace0, \ub54c\ub85c\ub294 \uc815\ub9d0 useCallback\uc744 \uc0ac\uc6a9\ud558\uc9c0 \uc54a\uc544 \ub9ac\ub80c\ub354\ub9c1\uc774 \ub9ce\uc774 \ubc1c\uc0dd\ud560 \uc218\ub3c4 \uc788\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4. \uc774 \uae00\uc5d0\uc11c\ub294 useCallback\uc774 \uc758\ubbf8\uc5c6\ub294 \ub54c\ub97c \uc18c\uac1c\ud558\uace0, \ub300\uc2e0 \uc0ac\uc6a9\ud560\ub9cc\ud55c \ud328\ud134\uc744 \uc18c\uac1c\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"245e548d-8a8e-8016-b271-c005bc61492e\\" id=\\"245e548d-8a8e-8016-b271-c005bc61492e\\">\uc694\uccad \uc2dc\uc5d0 <code>Cache-Control</code>\ub294 \uc5b4\ub5bb\uac8c \uc0ac\uc6a9\ub420\uae4c</h2><a href=\\"https://csswizardry.com/2025/03/why-do-we-have-a-cache-control-request-header/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://csswizardry.com/2025/03/why-do-we-have-a-cache-control-request-header/</a><p data-notion-block-id=\\"241e548d-8a8e-80ee-a3d7-f427c946e290\\">\uc694\uccad \uc2dc\uc5d0 <code>Cache-Control</code>\ud5e4\ub354\ub97c \uc9c1\uc811 \uc0ac\uc6a9\ud558\ub294 \uacbd\uc6b0\ub294 \ub4dc\ubb3c\uac81\ub2c8\ub2e4. \ub9ce\uc740 \uc0ac\ub78c\ub4e4\uc744 \uc704\ud574 \uc694\uccad \uc2dc\uc5d0 <code>Cache-Control</code> \ud5e4\ub354\uac00 \ube0c\ub77c\uc6b0\uc800\uc640 \uc0c8\ub85c\uace0\uce68 \ubc29\uc2dd\uc5d0 \ub530\ub77c \uc5b4\ub5bb\uac8c \ubcf4\ub0b4\uc9c0\ub294\uc9c0 \uc18c\uac1c\ud558\uace0, \uc694\uccad \uc2dc <code>Cache-Control</code>\ud5e4\ub354\ub97c \uc0ac\uc6a9\ud558\ub294 \uc608\uc2dc\ub97c \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"245e548d-8a8e-80df-b5b2-dda1ee172d08\\" id=\\"245e548d-8a8e-80df-b5b2-dda1ee172d08\\">Svelte 5 \ucef4\ud30c\uc77c\uc740 \uc5b4\ub5bb\uac8c \ub418\ub294\uac00</h2><a href=\\"https://lihautan.com/compile-svelte-5-in-your-head\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://lihautan.com/compile-svelte-5-in-your-head</a><p data-notion-block-id=\\"245e548d-8a8e-8077-a098-ea816781b5fc\\">\uac04\ub2e8\ud55c \uc608\uc81c\ub97c \ucef4\ud30c\uc77c\ud55c \uc608\uc81c\ub97c \ubcf4\uc5ec\uc8fc\ub294 \uac83\ubd80\ud130 \uc2dc\uc791\ud574\uc11c, \uc0c1\ud0dc(Rune)\uac00 \ud3ec\ud568\ub418\uc5c8\uc744 \ub54c\ub294 \uc5b4\ub5bb\uac8c \ucef4\ud30c\uc77c\ub418\ub294\uc9c0 \ubcf4\uc5ec\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4. Signal \uac1c\ub150\uc744 \ucc98\uc74c \uad6c\ud604\ud55c SolidJS\uc758 \uc81c\uc791\uc790\uc758 \ucc98\uc74c\ubd80\ud130 <a href=\\"https://dev.to/ryansolid/building-a-reactive-library-from-scratch-1i0p\\">Signal \ub77c\uc774\ube0c\ub7ec\ub9ac \uad6c\ud604\ud558\uae30</a>\ub3c4 \uc788\uc73c\ub2c8, Signal\uc744 \uc774\ud574\ud558\ub294\ub370 \ub354 \ub3c4\uc6c0\uc774 \ub420 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4 \ud83d\ude42 </p><h2 data-notion-block-id=\\"245e548d-8a8e-807e-82d6-cb0a56eaa604\\" id=\\"245e548d-8a8e-807e-82d6-cb0a56eaa604\\">RSC\ub294 SPA waterfall\uc744 \ud574\uacb0\ud588\uc744\uae4c</h2><a href=\\"https://devongovett.me/blog/parcel-rsc.html\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://devongovett.me/blog/parcel-rsc.html</a><p data-notion-block-id=\\"245e548d-8a8e-8038-b2af-d9e935eaf83d\\">\ubc88\ub4e4\ub7ec\uac00 \uc5b4\ub5bb\uac8c code spliting\ud558\ub294\uc9c0 \uc124\uba85\ud558\uace0, SPA\uc5d0\uc11c \ubc88\ub4e4 \ud30c\uc77c waterfall\uc774 \uc0dd\uacbc\ub294\uc9c0, \uadf8\ub9ac\uace0 \ubc88\ub4e4\ub7ec(Parcel)\uc5d0\uc11c\uc758 RSC\ub294 \uc774\ub97c \uc5b4\ub5bb\uac8c \ud574\uacb0\ud588\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ubaa8\ub4c8 \uc2dc\uc2a4\ud15c \uad00\uc810\uc5d0\uc11c \uc124\uba85\ud55c \uae00\uc740 <a href=\\"https://ones-to-watch.ethansup.net/news/post/211e548d-8a8e-8076-80cd-cabfc20df523#212e548d-8a8e-80de-b57c-d945e269c218\\">RSC\uc5d0\uc11c import\ub294 \uc5b4\ub5bb\uac8c \ub3d9\uc791\ud560\uae4c</a>\ub97c \ucc38\uace0\ud558\uc138\uc694.</p><h2 data-notion-block-id=\\"245e548d-8a8e-8039-886c-c83088d6f839\\" id=\\"245e548d-8a8e-8039-886c-c83088d6f839\\">Type\uc744 \uac12\ucc98\ub7fc \uc0ac\uc6a9\ud558\uae30</h2><a href=\\"https://gregros.dev/typescript/treating-types-as-values-with-type-level-maps\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://gregros.dev/typescript/treating-types-as-values-with-type-level-maps</a><p data-notion-block-id=\\"245e548d-8a8e-803b-9db3-c97ea1c5fc88\\">type-level maps\uac00 \ubb34\uc5c7\uc778\uc9c0, \uadf8\ub9ac\uace0 \ub9ce\uc740 type-safe \ub77c\uc774\ube0c\ub7ec\ub9ac\uac00 \uc5b4\ub5bb\uac8c type-level maps\ub85c type-safe\ub97c \ub2ec\uc131\ud558\ub294\uc9c0 \ubcf4\uc5ec\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4(\ubb3c\ub860 <a href=\\"https://ones-to-watch.ethansup.net/news/post/109e548d-8a8e-8006-bd2d-e5cd889b8dc5#109e548d-8a8e-8079-8c80-edd09db9fe25\\">\ucd94\ub860 \uc2dc\uac04\ub54c\ubb38\uc5d0 generate\ub85c \ubcc0\uacbd</a>\ud558\ub294 \uacbd\uc6b0\ub3c4 \uc788\uc2b5\ub2c8\ub2e4).</p><h1 data-notion-block-id=\\"241e548d-8a8e-8013-8675-c4249a6fc7d1\\">Straight to the Article: \ube5b\ub098\ub294 \uc778\uc0ac\uc774\ud2b8</h1><h2 data-notion-block-id=\\"245e548d-8a8e-8056-be96-fb6fdb0e9080\\" id=\\"245e548d-8a8e-8056-be96-fb6fdb0e9080\\">SPA\ub294 CSS\uc758 \ubc1c\uc804\uc774 \ub450\ub835\uc2b5\ub2c8\uae4c?</h2><a href=\\"https://www.jonoalderson.com/conjecture/its-time-for-modern-css-to-kill-the-spa/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.jonoalderson.com/conjecture/its-time-for-modern-css-to-kill-the-spa/</a><p data-notion-block-id=\\"245e548d-8a8e-8080-b248-d653105618b6\\">\uac04\ub2e8\ud55c SPA\ub294 \ubb34\uac81\uace0, \uc131\ub2a5 \uc0c1 \uc88b\uc9c0 \uc54a\ub2e4\ub294 \uac83\uc744 \uac15\uc870\ud558\uace0, View Transistion API\uacfc Speculation rules API\uac00 SPA\ub97c \ub300\uc2e0\ud560 \uc218 \uc788\uc744 \uac83\uc774\ub77c\ub294 \uae00\uc785\ub2c8\ub2e4. SPA\uc5d0\uc11c\uc758 Tanstack Query\ub098 Relay\uac19\uc740 fetching \ubc29\uc2dd\uc758 \ubc1c\uc804\uacfc \ud504\ub808\uc784\uc6cc\ud06c\uc758 \ubc1c\uc804\uc73c\ub85c Partial Hydration\uc758 \ubc1c\uc804\uacfc \uac19\uc774 \uc5ec\ub7ec \uc0dd\ud0dc\uacc4\uc758 \ub178\ub825\uc73c\ub85c 100\ud37c\uc13c\ud2b8 \ub3d9\uc758\ud558\uc9c0\ub294 \uc54a\uc9c0\ub9cc, View Transistion API\uacfc Speculation rules API\uc758 \ubc1c\uc804\uc740 \uc9c0\ucf1c\ubcfc\ub9cc \ud558\uaca0\ub124\uc694 :)</p><h2 data-notion-block-id=\\"245e548d-8a8e-807d-b43b-e1a661e39af6\\" id=\\"245e548d-8a8e-807d-b43b-e1a661e39af6\\">Node.js\uc640 DNS \uce90\uc2f1</h2><a href=\\"https://marmelab.com/blog/2025/07/28/dns-in-nodejs.html\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://marmelab.com/blog/2025/07/28/dns-in-nodejs.html</a><p data-notion-block-id=\\"245e548d-8a8e-80cd-9c66-d935e2794c13\\">DNS\uc5d0 \ub300\ud55c \uc124\uba85, \uadf8\ub9ac\uace0 \uc65c DNS\uac00 Node.js\uc758 \uc131\ub2a5\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce58\ub294\uc9c0, \uc5b4\ub5bb\uac8c \ud574\uacb0\ud588\ub294\uc9c0\ub97c \ubcf4\uc5ec\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"245e548d-8a8e-8058-82a6-c03a82f3a429\\" id=\\"245e548d-8a8e-8058-82a6-c03a82f3a429\\"><code>spyOn</code>\uc744 \uae30\ubcf8\uc73c\ub85c \uc0ac\uc6a9\ud558\uc790</h2><a href=\\"https://laconicwit.com/vi-mock-is-a-footgun-why-vi-spyon-should-be-your-default/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://laconicwit.com/vi-mock-is-a-footgun-why-vi-spyon-should-be-your-default/</a><p data-notion-block-id=\\"245e548d-8a8e-8032-a635-f41155a516b5\\">\ud14c\uc2a4\ud2b8 \ucf54\ub4dc\ub97c \uc9e4 \uacbd\uc6b0\uc5d0 \uc5b4\ub5a8 \ub54c <code>mock</code>\uc744 \uc368\uc57c \ud558\ub294\uc9c0 <code>spyOn</code>\uc744 \uae30\ubcf8\uc73c\ub85c \uc4f0\uba74 \uc88b\uc740 \uc810\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"245e548d-8a8e-809a-a8ba-fc371e8b043e\\" id=\\"245e548d-8a8e-809a-a8ba-fc371e8b043e\\">\uc218\ub9ce\uc740 JS \ub7f0\ud0c0\uc784\uc774 \uc788\uc5c8\ub2e4.</h2><a href=\\"https://buttondown.com/whatever_jamie/archive/the-many-many-many-javascript-runtimes-of-the-last-decade/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://buttondown.com/whatever_jamie/archive/the-many-many-many-javascript-runtimes-of-the-last-decade/</a><h2 data-notion-block-id=\\"245e548d-8a8e-80ee-9d4d-e3193e9248b9\\" id=\\"245e548d-8a8e-80ee-9d4d-e3193e9248b9\\">\uc720\ud29c\ube0c \ub300\uc2e0, \ubc18\uc751\ud615 \ube44\ub514\uc624 \uc0ac\uc6a9\ud558\uae30</h2><a href=\\"https://www.kooslooijesteijn.net/blog/responsive-video-easy\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.kooslooijesteijn.net/blog/responsive-video-easy</a><h1 data-notion-block-id=\\"241e548d-8a8e-803f-a4fc-d94bcfafb77b\\">Fresh Finds: \ub193\uce58\uc9c0 \ub9d0\uc544\uc57c \ud560 \uc18c\uc2dd</h1><a href=\\"https://blog.swmansion.com/reanimated-4-stable-release-the-future-of-react-native-animations-ba68210c3713\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.swmansion.com/reanimated-4-stable-release-the-future-of-react-native-animations-ba68210c3713</a><p data-notion-block-id=\\"245e548d-8a8e-80b7-8069-ea35889e048f\\">React Native Reanimated 4\uc5d0\uc11c\ub294 CSS \uc560\ub2c8\uba54\uc774\uc158\uacfc transition API\ub97c \uae30\ubc18\uc73c\ub85c RN\uc5d0\uc11c \uc560\ub2c8\uba54\uc774\uc158\uc744 \ub9cc\ub4e4 \uc218 \uc788\uac8c \ub418\uc5c8\uc2b5\ub2c8\ub2e4.</p><a href=\\"https://expo.dev/blog/precompiled-react-native-for-ios\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://expo.dev/blog/precompiled-react-native-for-ios</a><p data-notion-block-id=\\"246e548d-8a8e-8068-b8d6-c0612d894daa\\">RN 0.81\ubc84\uc804\ubd80\ud130 pre-compile\ub41c \ube4c\ub4dc\uac00 \ub3c4\uc785\ub418\uc5b4 \ube4c\ub4dc\uc2dc\uac04 \ub2e8\ucd95\uc774 \uac00\ub2a5\ud569\ub2c8\ub2e4(expo\uc5d0\uc11c\ub3c4\uc694!).</p>"}')}}]);